WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='PRUEBAS_FINALES_NEUMATICAS' AND v.numero=1),d(t,o) AS (VALUES('DATOS DE ENSAYO',1),('FRENO DE SERVICIO',2),('FRENO DE ESTACIONAMIENTO',3),('LISTA DE INSTRUMENTOS',4),('OBSERVACIONES:',5),('PERSONAL',6)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='PRUEBAS_FINALES_NEUMATICAS' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),d(t,c,e,ty,o,cf) AS (VALUES('DATOS DE ENSAYO','tren','TREN N°','texto',1,'{}'),('DATOS DE ENSAYO','fecha_prueba','Fecha de Prueba:','fecha',2,'{}'),('FRENO DE SERVICIO','servicio','FRENO DE SERVICIO','tabla',1,'{"columnas":[{"codigo":"coche","etiqueta":"OPERACIONES"},{"codigo":"valor_inicial_bar","etiqueta":"Valor inicial (bar)"},{"codigo":"valor_10_min_bar","etiqueta":"Valor visualizado (bar) (tras 10 min)"},{"codigo":"evaluacion","etiqueta":"√ / X","tipo":"seleccion","opciones":[{"valor":"conforme","etiqueta":"√"},{"valor":"no_conforme","etiqueta":"X"}]}],"filasIniciales":[{"coche":"MA1","referencia":"1,8 bar ±0,2"},{"coche":"MB1","referencia":"1,8 bar ±0,2"},{"coche":"R","referencia":"1,8 bar ±0,2"},{"coche":"MB2","referencia":"1,8 bar ±0,2"},{"coche":"MA2","referencia":"1,8 bar ±0,2"},{"coche":"Revisar la instalación neumática en busca de fugas.","referencia":"No se detectan fugas en la instalación"}]}'),('FRENO DE ESTACIONAMIENTO','estacionamiento','FRENO DE ESTACIONAMIENTO','tabla',1,'{"columnas":[{"codigo":"coche","etiqueta":"OPERACIONES"},{"codigo":"valor_inicial_bar","etiqueta":"Valor inicial (bar)"},{"codigo":"valor_10_min_bar","etiqueta":"Valor visualizado (bar) (tras 10 min)"},{"codigo":"evaluacion","etiqueta":"√ / X","tipo":"seleccion","opciones":[{"valor":"conforme","etiqueta":"√"},{"valor":"no_conforme","etiqueta":"X"}]}],"filasIniciales":[{"coche":"MA1","referencia":"7,7 bar ±0,2"},{"coche":"MB1","referencia":"7,7 bar ±0,2"},{"coche":"R","referencia":"7,7 bar ±0,2"},{"coche":"MB2","referencia":"7,7 bar ±0,2"},{"coche":"MA2","referencia":"7,7 bar ±0,2"},{"coche":"Verificar el desbloqueo del freno de estacionamiento","referencia":"Se afloja el freno de estacionamiento mecanicamente"}]}'),('LISTA DE INSTRUMENTOS','instrumentos','LISTA DE INSTRUMENTOS','tabla',1,'{"columnas":[{"codigo":"codigo","etiqueta":"Código"},{"codigo":"descripcion","etiqueta":"Descripción del equipo"},{"codigo":"marca_modelo","etiqueta":"Marca/Modelo"},{"codigo":"calibracion","etiqueta":"Fecha de Calibración/Verificación"},{"codigo":"observaciones","etiqueta":"Observaciones"}],"filasIniciales":[{},{},{},{},{}]}'),('OBSERVACIONES:','observaciones','OBSERVACIONES:','texto',1,'{"multilinea":true}'),('PERSONAL','personal','PERSONAL','tabla',1,'{"columnas":[{"codigo":"cargo","etiqueta":"CARGO"},{"codigo":"firma","etiqueta":"FIRMA","tipo":"firma"}],"filasIniciales":[{"cargo":"TÉCNICO:"},{"cargo":"TÉCNICO:"},{"cargo":"SUPERVISOR:"}]}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf::jsonb FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
